if __name__ == "__main__":
    fn = sys.argv[1]
    lines = get_lines(fn)
    nl = []
    remained = []
    for line in lines:
        striped = line.strip()
        if "<:" in striped or ">:" in striped:
            continue

        #        text = re.sub(r"</?[A-Za-z][^>]*>", "", striped)
        text = re.sub(r"<[^>]*>", "", striped)

        #        striped = tag_re.sub("", striped)
        nl.append(text)
    with open(fn, "w", encoding="utf8") as f:
        for k in nl:
            f.write(f"{k}\n")
    if remained:
        with open("remained", "w", encoding="utf8") as fr:
            for x in remained:
                fr.write(f"{x}\n")
